import{_ as t,o,c as n,ag as a}from"./chunks/framework.Cyu1VozZ.js";const g=JSON.parse('{"title":"Build a Deck","description":"","frontmatter":{},"headers":[],"relativePath":"slides/build-a-deck.md","filePath":"slides/build-a-deck.md"}'),r={name:"slides/build-a-deck.md"};function s(i,e,l,d,h,c){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="build-a-deck" tabindex="-1">Build a Deck <a class="header-anchor" href="#build-a-deck" aria-label="Permalink to &quot;Build a Deck&quot;">​</a></h1><p>In this guide, you&#39;ll build a short three-slide deck from scratch. Along the way, you&#39;ll pick a theme, use a layout, add text and a shape, and present the deck full-screen.</p><h2 id="_1-create-a-new-presentation" tabindex="-1">1. Create a New Presentation <a class="header-anchor" href="#_1-create-a-new-presentation" aria-label="Permalink to &quot;1. Create a New Presentation&quot;">​</a></h2><p>From your workspace, click <strong>New</strong> → <strong>New Presentation</strong>. You&#39;ll get a deck with one slide — an empty canvas, using the <strong>Blank</strong> layout — and a thumbnail strip on the left.</p><h2 id="_2-pick-a-theme" tabindex="-1">2. Pick a Theme <a class="header-anchor" href="#_2-pick-a-theme" aria-label="Permalink to &quot;2. Pick a Theme&quot;">​</a></h2><p>A <strong>theme</strong> controls the colors, fonts, and background used across every slide. Wafflebase ships with several built-in themes.</p><p>Click the palette button in the toolbar (tooltip: <strong>Theme</strong>) to open the Theme panel on the right, then click any theme to apply it to the whole deck. You can switch themes any time — your content stays put.</p><p>See <a href="./themes-and-layouts.html">Themes &amp; Layouts</a> for the full set of built-in themes and how to customize one.</p><h2 id="_3-add-a-title" tabindex="-1">3. Add a Title <a class="header-anchor" href="#_3-add-a-title" aria-label="Permalink to &quot;3. Add a Title&quot;">​</a></h2><p>The first slide starts blank, so give it a layout: right-click an empty part of the canvas, choose <strong>Change layout…</strong>, and pick <strong>Title slide</strong>. The slide now has a title and a subtitle placeholder.</p><p>Double-click the title placeholder and type a deck title — for example, <code>Q2 Roadmap</code>. Double-click the subtitle placeholder and add a short tagline.</p><p>The placeholders inherit the heading and body fonts from the active theme, so you don&#39;t need to format text manually.</p><h2 id="_4-add-a-content-slide" tabindex="-1">4. Add a Content Slide <a class="header-anchor" href="#_4-add-a-content-slide" aria-label="Permalink to &quot;4. Add a Content Slide&quot;">​</a></h2><p>Insert a new slide after the current one. The three routes differ in which layout the new slide gets:</p><table tabindex="0"><thead><tr><th>How</th><th>Layout of the new slide</th></tr></thead><tbody><tr><td>Press <code>⌘+M</code> / <code>Ctrl+M</code></td><td>Same layout as the slide you&#39;re on</td></tr><tr><td>Click <strong>Add slide</strong> in the toolbar</td><td>Blank</td></tr><tr><td>Right-click the thumbnail strip → <strong>New slide</strong></td><td>Blank</td></tr></tbody></table><p>To choose the layout as you insert, click the chevron next to <strong>Add slide</strong> — its tooltip reads <strong>Choose a layout</strong> — and pick <strong>Title and body</strong>. That adds a <em>new</em> slide with that layout; it does not re-lay-out the slide you&#39;re on. (For that, see <a href="./themes-and-layouts.html#choosing-a-layout">Choosing a Layout</a>.)</p><p>Type a title — <code>Themes</code> — and add a few bullet points in the body placeholder:</p><ul><li>Theme picker in the right sidebar</li><li>One-click reskin of the whole deck</li><li>Built-in light and dark themes</li></ul><h2 id="_5-add-a-shape" tabindex="-1">5. Add a Shape <a class="header-anchor" href="#_5-add-a-shape" aria-label="Permalink to &quot;5. Add a Shape&quot;">​</a></h2><p>Slides ship with an OOXML-aligned shape library. From the toolbar, click <strong>Shape</strong> and pick a rectangle. Drag on the canvas to draw it.</p><p>With the shape selected, the <strong>Fill</strong> color in the toolbar shows the active theme palette at the top — so you can apply the theme&#39;s accent color without picking a hex value.</p><h2 id="_6-present" tabindex="-1">6. Present <a class="header-anchor" href="#_6-present" aria-label="Permalink to &quot;6. Present&quot;">​</a></h2><p>When you&#39;re ready to present:</p><ul><li>Press <code>⌘+Enter</code> / <code>Ctrl+Enter</code> to start from the current slide, <strong>or</strong></li><li>Press <code>⌘+Shift+Enter</code> / <code>Ctrl+Shift+Enter</code> to start from the first slide.</li></ul><p>In presentation mode:</p><ul><li><code>→</code> / <code>Page Down</code> / click — advance to the next slide</li><li><code>←</code> / <code>Page Up</code> — go back</li><li><code>Esc</code> — exit</li></ul><h2 id="format-options" tabindex="-1">Format Options <a class="header-anchor" href="#format-options" aria-label="Permalink to &quot;Format Options&quot;">​</a></h2><p>Most per-object settings that aren&#39;t on the toolbar live in the <strong>Format options</strong> panel. Open it with the sliders button at the right end of the toolbar (tooltip: <strong>Format options</strong>). With nothing selected it shows <strong>Slide size</strong> — Widescreen 16:9, Standard 4:3, or Widescreen 16:10.</p><p>Slide <strong>width is fixed</strong> and its box is disabled; only the <strong>Height</strong> changes, which is what changes the aspect ratio. To go to a size that isn&#39;t one of the three presets, type a height — the preset dropdown then reads <em>Custom</em> on its own. Picking <strong>Custom</strong> from the dropdown does nothing.</p><p>Select something and the panel shows the sections that apply to it:</p><table tabindex="0"><thead><tr><th>Section</th><th>Appears for</th><th>What&#39;s in it</th></tr></thead><tbody><tr><td><strong>Size &amp; Position</strong></td><td>Everything</td><td>Width, Height, X position, Y position, Rotation, a <strong>Lock aspect ratio</strong> toggle, two 90° rotate buttons, and a deck-wide <strong>Units</strong> choice of Inches or Centimeters</td></tr><tr><td><strong>Text fitting</strong></td><td>Text boxes</td><td>Do not autofit / Shrink text on overflow / Resize shape to fit text</td></tr><tr><td><strong>Recolor</strong></td><td>Images</td><td>No recolor / Grayscale / Sepia</td></tr><tr><td><strong>Adjustments</strong></td><td>Images</td><td>Transparency, Brightness, Contrast</td></tr><tr><td><strong>Drop shadow</strong></td><td>Shapes, images, text boxes</td><td>Color, Transparency, Angle, Distance, Blur</td></tr><tr><td><strong>Reflection</strong></td><td>Shapes, images, text boxes</td><td>Transparency, Distance, Size</td></tr><tr><td><strong>Alt text</strong></td><td>Shapes, images, text boxes, tables</td><td>A description for screen readers</td></tr></tbody></table><p>Connectors and groups get <strong>Size &amp; Position</strong> only, and tables get <strong>Size &amp; Position</strong> and <strong>Alt text</strong>. Width, Height, and Rotation are hidden for connectors, and a text box set to <em>Resize shape to fit text</em> has its Height locked, since it&#39;s computed from the content.</p><h2 id="rulers-guides-and-snapping" tabindex="-1">Rulers, Guides, and Snapping <a class="header-anchor" href="#rulers-guides-and-snapping" aria-label="Permalink to &quot;Rulers, Guides, and Snapping&quot;">​</a></h2><p>Rulers run along the top and left of the canvas. They&#39;re always on — there&#39;s no show/hide command — and they use inches or centimetres based on your locale, independently of the <strong>Units</strong> choice in the Format options panel.</p><p>To place a <strong>guide</strong>, press on a ruler and drag onto the slide; release inside the slide to drop it, or outside to cancel. Drag an existing guide to move it, or drag it back onto a ruler to delete it. Right-clicking on or near a guide offers <strong>Delete guide</strong>, <strong>Delete all vertical guides</strong> / <strong>Delete all horizontal guides</strong>, and <strong>Delete all guides</strong>.</p><p>Guides belong to the whole presentation, not to one slide.</p><p>Snapping is always on as you drag: elements snap to the slide centre, to your guides, and to other elements&#39; edges. <strong>Smart guides</strong> — the arrows and dashed outlines showing equal spacing or matching sizes — are always on too; neither has a setting. Hold <code>Shift</code> while resizing to <strong>preserve the aspect ratio</strong> (which also turns off equal-size snapping, since the two would fight), and <code>Shift</code> while dragging to lock movement to one axis.</p><h2 id="copy-formatting-between-objects" tabindex="-1">Copy Formatting Between Objects <a class="header-anchor" href="#copy-formatting-between-objects" aria-label="Permalink to &quot;Copy Formatting Between Objects&quot;">​</a></h2><p>The brush button in the toolbar (tooltip: <strong>Format painter</strong>) copies fill and stroke from one object to another:</p><ol><li>Select a single shape, text box, or connector.</li><li>Click <strong>Format painter</strong>.</li><li>Click the object you want to paint.</li></ol><p>It applies once and switches itself off — there is no double-click-to-stay-on mode, and no keyboard shortcut. Click the button again, or press <code>Esc</code>, to cancel without painting. Selecting nothing (or more than one object) makes the button do nothing, and images can&#39;t be used as a source.</p><p>Shapes and text boxes share a fill and stroke, so you can paint either way between them — a shape&#39;s formatting onto a text box, or the reverse. (Painting onto text keeps only a solid colour: a gradient fill collapses to one of its colours.) Connectors are the exception: they carry a stroke only, so a connector can be painted onto another connector and nothing else, and nothing else can be painted onto a connector.</p><h2 id="crop-an-image" tabindex="-1">Crop an Image <a class="header-anchor" href="#crop-an-image" aria-label="Permalink to &quot;Crop an Image&quot;">​</a></h2><p>Select an image and click the crop button in the toolbar (tooltip: <strong>Crop</strong>), or just double-click the image. The picture dims outside the crop window, and eight black handles appear on the window itself:</p><ul><li>Drag a handle to trim.</li><li>Drag <em>inside</em> the window to slide the picture under it.</li><li>Press <code>Enter</code>, click the toolbar button again (now <strong>Done cropping</strong>), or click anywhere outside the crop window to apply.</li><li>Press <code>Esc</code> to cancel.</li></ul><p><strong>Reset crop</strong>, next to the crop button, restores the full picture in one undo step; it&#39;s greyed out until the image has actually been cropped.</p><p>Cropping is a free rectangle only — there are no aspect-ratio presets and no crop-to-shape. Images inside a group can&#39;t be cropped; ungroup first.</p><h2 id="speaker-notes" tabindex="-1">Speaker Notes <a class="header-anchor" href="#speaker-notes" aria-label="Permalink to &quot;Speaker Notes&quot;">​</a></h2><p>Every slide has a speaker-notes box below the canvas, showing the placeholder <strong>Speaker notes…</strong> when it&#39;s empty. Click into it and type — notes are saved with the slide, and switching slides switches the notes with them.</p><p>The pane is always visible; there is no show/hide toggle. Drag the thin divider directly above it to make it taller or shorter (the size is remembered per browser). It can be shrunk but not collapsed away entirely.</p><p>Two limits worth knowing:</p><ul><li><strong>Notes are plain text.</strong> There is no bold, italic, or bullet formatting in the notes box.</li><li><strong>They are not shown while presenting.</strong> There is no presenter view or second-screen notes display — presentation mode shows the slide only. Notes <em>are</em> written into a <code>.pptx</code> export as real PowerPoint notes, so a deck you export keeps them; a PDF export does not include them.</li></ul><p>Notes are last-write-wins if two people type in them at once — see <a href="#editing-at-the-same-time">Editing at the Same Time</a> below.</p><h2 id="editing-at-the-same-time" tabindex="-1">Editing at the Same Time <a class="header-anchor" href="#editing-at-the-same-time" aria-label="Permalink to &quot;Editing at the Same Time&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Two people in the same text lose one set of edits</p><p>Text in a deck is <strong>not</strong> merged character by character the way it is in the document editor. Speaker notes, text boxes, shape text, and table cells each commit their whole contents when you click away, so the last person to click away overwrites what the other typed — silently, with no conflict prompt.</p><p>Presence cursors show you where others are working; use them to keep out of each other&#39;s text, or take turns.</p></div><p>Structural edits converge without losing work: adding, deleting, duplicating, and reordering slides; adding, deleting, and restacking elements; table row and column changes; and theme and guide changes. Moving or restyling elements settles per field on the last change committed, so two people dragging <em>different</em> elements are fine — it&#39;s two people in the same text box, or the same notes, that costs somebody their edits.</p><h2 id="arrange-align-and-order" tabindex="-1">Arrange, Align, and Order <a class="header-anchor" href="#arrange-align-and-order" aria-label="Permalink to &quot;Arrange, Align, and Order&quot;">​</a></h2><p>With one or more elements selected, the <strong>Arrange</strong> button in the toolbar (the stacked-layers icon) collects the positioning commands:</p><table tabindex="0"><thead><tr><th>Menu entry</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Group</strong> / <strong>Ungroup</strong></td><td>Bind the selection into one object, or break it apart. Group needs 2+ elements selected; Ungroup needs a single selected group.</td></tr><tr><td><strong>Order</strong> → Bring to front / Bring forward / Send backward / Send to back</td><td>Move the selection up and down the stacking order.</td></tr><tr><td><strong>Align</strong> → Left / Center / Right / Top / Middle / Bottom</td><td>With several elements selected, aligns them to each other. With just one selected, aligns it to the slide.</td></tr><tr><td><strong>Distribute</strong> → Horizontally / Vertically</td><td>Even out the gaps. Needs <strong>3 or more</strong> elements — the outermost two stay put and the ones between them move.</td></tr><tr><td><strong>Rotate 90° clockwise</strong> / <strong>Rotate 90° counter-clockwise</strong></td><td>Each selected element turns about its own center.</td></tr></tbody></table><p>Each command counts as a single undo step, and every element keeps whatever rotation it already had.</p><p>The <strong>Arrange</strong> button only appears while something is selected — with an empty selection the toolbar shows its idle tools instead.</p><h2 id="add-a-table" tabindex="-1">Add a Table <a class="header-anchor" href="#add-a-table" aria-label="Permalink to &quot;Add a Table&quot;">​</a></h2><p>Click the <strong>Insert table</strong> button in the toolbar and drag across the grid picker to choose the number of rows and columns, then click to drop the table on the slide.</p><ul><li><strong>Double-click</strong> a cell to edit its text; the text-formatting toolbar appears while you type.</li><li><strong>Tab</strong> / <strong>Shift+Tab</strong> move between cells — pressing Tab in the last cell adds a new row.</li><li><strong>Right-click</strong> a cell for structure changes: <strong>Insert row above/below</strong>, <strong>Insert column left/right</strong>, <strong>Delete row/column</strong>, and <strong>Merge cells</strong> / <strong>Unmerge cells</strong>.</li></ul><h2 id="connect-shapes" tabindex="-1">Connect Shapes <a class="header-anchor" href="#connect-shapes" aria-label="Permalink to &quot;Connect Shapes&quot;">​</a></h2><p>Use connectors to link shapes — handy for flowcharts and diagrams. Click the <strong>Line</strong> dropdown in the toolbar and pick a tool:</p><ul><li><strong>Line</strong> and <strong>Arrow</strong> — straight connectors.</li><li><strong>Elbow connector</strong> — right-angled routing.</li><li><strong>Curved connector</strong> — a smooth curve.</li><li><strong>Scribble</strong> — freehand drawing, not a connector.</li></ul><p>Drag from the start point to the end point. As you approach a shape, connection points appear and the endpoint snaps to it, so the connector stays attached when you later move the shape. To change the routing of a selected connector, right-click it and choose <strong>Straight</strong>, <strong>Elbow</strong>, or <strong>Curved</strong>.</p><h2 id="animations-transitions" tabindex="-1">Animations &amp; Transitions <a class="header-anchor" href="#animations-transitions" aria-label="Permalink to &quot;Animations &amp; Transitions&quot;">​</a></h2><p>Click the sparkles button in the toolbar (tooltip: <strong>Motion</strong>) to open the Motion panel on the right.</p><p><strong>Slide transitions</strong> (how one slide gives way to the next):</p><ol><li>In the <strong>Transition</strong> section, pick a type — Fade, Dissolve, Slide, Flip, Cube, Wipe, or Push.</li><li>Choose a speed (Slow / Medium / Fast).</li><li>Click <strong>Apply to all slides</strong> to use the same transition everywhere.</li></ol><p><strong>Object animations</strong> (how an element enters, exits, or is emphasized):</p><ol><li>Select an element on the slide.</li><li>In the <strong>Animation</strong> section, click <strong>+ Add animation</strong>.</li><li>Pick a <strong>Category</strong> (Entrance, Exit, or Emphasis) and an <strong>Effect</strong>, then set when it runs with <strong>Start</strong> — <strong>On Click</strong>, <strong>With Previous</strong>, or <strong>After Previous</strong>. Fine-tune <strong>Duration</strong>, <strong>Delay</strong>, and <strong>Easing</strong> as needed.</li></ol><p>Click the <strong>▶ Play</strong> button to preview the animations right in the editor. They also run when you present the deck.</p><h2 id="charts-in-an-imported-deck" tabindex="-1">Charts in an Imported Deck <a class="header-anchor" href="#charts-in-an-imported-deck" aria-label="Permalink to &quot;Charts in an Imported Deck&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Exporting to PowerPoint drops imported charts</p><p>If you import a <code>.pptx</code> that contains charts, they appear on the slides and they render in a PDF export — but <strong>a PowerPoint (<code>.pptx</code>) export omits them, with no warning</strong>. The rest of the deck exports normally; the chart is simply absent from the exported file.</p></div><p>In a deck, charts can only arrive by importing a PowerPoint file — the slides toolbar has no insert-chart tool, and an imported chart cannot be edited. You can move and resize it, but its numbers, series, and type are fixed at whatever PowerPoint last saved. (Spreadsheets <em>do</em> have an <strong>Insert chart</strong> button; see <a href="/docs/sheets/charts.html">Charts &amp; Pivot Tables</a>.)</p><p>If you need a round-trip through <code>.pptx</code> on a deck with charts, keep the original file, or rebuild the chart as a picture before exporting.</p><p>See <a href="/docs/guide/import-export.html">Import &amp; Export</a> for the full format support table.</p><h2 id="what-s-next" tabindex="-1">What&#39;s Next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s Next&quot;">​</a></h2><ul><li><a href="./themes-and-layouts.html">Themes &amp; Layouts</a> — Catalog of themes, layouts, and placeholders</li><li><a href="./keyboard-shortcuts.html">Keyboard Shortcuts</a> — Full shortcut reference</li><li><a href="/docs/guide/collaboration.html">Collaboration &amp; Sharing</a> — Invite others to co-edit the deck</li></ul>',82)])])}const u=t(r,[["render",s]]);export{g as __pageData,u as default};
